mapper.select:
SELECT tdm64_chck_evid_extr_id
  FROM tdm64_chck_evid_extr
 WHERE tdm64_target_id = #{targetId}

mapper.update:
UPDATE tdm64_chck_evid_extr
   SET tdm64_system_nm = #{row.systemName}
     , tdm64_doc_no    = #{row.docNo}
     , tdm64_doc_nm    = #{row.docName}
     , tdm64_doc_date  = CAST(#{row.docDate} AS date)
     , tdm64_note      = #{row.note}
     , tdm64_upd_nm    = #{updName}
     , tdm64_upd_date  = f_sysdate()
 WHERE tdm64_chck_evid_extr_id = #{row.chckEvidExtrId}
   AND tdm64_target_id         = #{targetId}

mapper.delete:
DELETE FROM tdm64_chck_evid_extr
 WHERE tdm64_target_id = #{targetId}
   AND tdm64_chck_evid_extr_id IN
#{id}
